const CONFIG = {
  // Isi keduanya untuk uji tanpa Olsera. Kosongkan di produksi.
  MANUAL_CUSTOMER_NAME: '',
  MANUAL_PRODUCT_NAME: '',
  MANUAL_BUSINESS_DATE: '',
  LOOKBACK_DAYS: 1,
  WUNPAID: '0',
  PER_PAGE: 50,
  TIMEZONE: 'Asia/Jakarta',
  SOURCE_ENDPOINT: 'https://api-open.olsera.co.id/api/open-api/v1/en/report/salesdetails',
  VIDEO_MODEL: 'grok-imagine-video-1.5',
  CHAT_MODEL: 'grok-4.6',
  VIDEO_DURATION: 8,
  VIDEO_ASPECT_RATIO: '9:16',
  VIDEO_RESOLUTION: '720p',
  MAX_POLLS: 30,
  POLL_SECONDS: 20,
};

const xaiKey = String($env.XAI_API_KEY ?? '').trim();
if (!xaiKey) {
  throw new Error('XAI_API_KEY belum diisi pada environment stack n8n.');
}

const ymdInTimezone = (date) => {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: CONFIG.TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const values = Object.fromEntries(
    parts.filter((part) => part.type !== 'literal').map((part) => [part.type, part.value])
  );
  return values.year + '-' + values.month + '-' + values.day;
};

const isStrictYmd = (value) => /^\d{4}-\d{2}-\d{2}$/.test(String(value || ''));

let businessDate = String(CONFIG.MANUAL_BUSINESS_DATE || '').trim();
if (businessDate && !isStrictYmd(businessDate)) {
  throw new Error('MANUAL_BUSINESS_DATE harus berformat YYYY-MM-DD.');
}

if (!businessDate) {
  const today = ymdInTimezone(new Date());
  const cursor = new Date(today + 'T12:00:00+07:00');
  cursor.setUTCDate(cursor.getUTCDate() - CONFIG.LOOKBACK_DAYS);
  businessDate = ymdInTimezone(cursor);
}

const manualCustomer = String(CONFIG.MANUAL_CUSTOMER_NAME || '').trim();
const manualProduct = String(CONFIG.MANUAL_PRODUCT_NAME || '').trim();
const useManual = Boolean(manualCustomer && manualProduct);

if ((manualCustomer && !manualProduct) || (!manualCustomer && manualProduct)) {
  throw new Error('Isi MANUAL_CUSTOMER_NAME dan MANUAL_PRODUCT_NAME bersamaan, atau kosongkan keduanya.');
}

return [{
  json: {
    use_manual: useManual,
    skipped: false,
    business_date: businessDate,
    customer_name: manualCustomer,
    product_name: manualProduct,
    wunpaid: CONFIG.WUNPAID,
    per_page: CONFIG.PER_PAGE,
    source_endpoint: CONFIG.SOURCE_ENDPOINT,
    timezone: CONFIG.TIMEZONE,
    video_model: CONFIG.VIDEO_MODEL,
    chat_model: CONFIG.CHAT_MODEL,
    video_duration: CONFIG.VIDEO_DURATION,
    video_aspect_ratio: CONFIG.VIDEO_ASPECT_RATIO,
    video_resolution: CONFIG.VIDEO_RESOLUTION,
    max_polls: CONFIG.MAX_POLLS,
    poll_seconds: CONFIG.POLL_SECONDS,
  },
}];

const response = $input.first().json;
const rawToken =
  response?.access_token ??
  response?.data?.access_token ??
  response?.result?.access_token ??
  response?.token?.access_token ??
  response?.data?.token;

if (!rawToken || !String(rawToken).trim()) {
  throw new Error(
    'Access token tidak ditemukan pada respons Olsera. Field tingkat atas: ' +
    (Object.keys(response ?? {}).join(', ') || '(kosong)') + '.'
  );
}

const accessToken = String(rawToken).trim().replace(/^Bearer\s+/i, '');
if (!accessToken) {
  throw new Error('Access token Olsera kosong setelah normalisasi.');
}

const config = $('Tanggal Bisnis & Konfigurasi').first().json;
return [{ json: { ...config, access_token: accessToken } }];

const response = $input.first().json;
const config = $('Tanggal Bisnis & Konfigurasi').first().json;

const firstDefined = (...values) =>
  values.find((value) => value !== undefined && value !== null && String(value).trim() !== '');

const toText = (...values) => {
  const value = firstDefined(...values);
  return value === undefined ? '' : String(value).trim();
};

const readPath = (source, path) => {
  return String(path).split('.').reduce((acc, key) => {
    if (acc === undefined || acc === null) return undefined;
    return acc[key];
  }, source);
};

const TITLE_SKIP = new Set([
  'bapak', 'ibu', 'pak', 'bu', 'kak', 'mas', 'mba', 'mbak',
  'sdr', 'sdri', 'tn', 'ny', 'bpk', 'bpk.', 'ibu.',
]);

const toFirstName = (fullName) => {
  const cleaned = String(fullName || '')
    .replace(/[^A-Za-zÀ-ÿ' .\-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!cleaned) return '';
  const parts = cleaned.split(' ').filter(Boolean);
  const picked = TITLE_SKIP.has(parts[0].toLowerCase()) ? (parts[1] || '') : parts[0];
  if (!picked || picked.length < 2) return '';
  return picked.charAt(0).toUpperCase() + picked.slice(1).toLowerCase();
};

const cleanProduct = (name) => {
  const cleaned = String(name || '').replace(/\s+/g, ' ').trim();
  if (!cleaned) return '';
  return cleaned.length > 80 ? cleaned.slice(0, 77).trim() + '...' : cleaned;
};

const looksCancelled = (row) => {
  const blob = [
    row?.status,
    row?.order_status,
    row?.payment_status,
    row?.pay_status,
    row?.state,
  ].map((value) => String(value || '').toLowerCase()).join(' ');
  return /cancel|batal|void|refund|unpaid|belum\s*bayar/.test(blob);
};

const listCandidates = [
  response,
  response?.data,
  response?.data?.data,
  response?.result,
  response?.items,
  response?.rows,
  response?.orders,
  response?.data?.items,
  response?.data?.rows,
  response?.data?.orders,
  response?.data?.result,
];
const rows = listCandidates.find((value) => Array.isArray(value)) || [];

const purchases = [];
for (const row of rows) {
  if (!row || typeof row !== 'object' || looksCancelled(row)) continue;

  const customerRaw = toText(
    row.customer_name,
    row.cust_name,
    row.buyer_name,
    row.member_name,
    row.nama_pelanggan,
    row.customer?.name,
    row.customer?.customer_name,
    row.member?.name,
    readPath(row, 'customer.fullname')
  );
  const productRaw = toText(
    row.product_name,
    row.item_name,
    row.sku_name,
    row.nama_produk,
    row.product?.name,
    row.item?.name,
    row.item?.product_name,
    readPath(row, 'items.0.product_name'),
    readPath(row, 'items.0.name')
  );

  const customerName = toFirstName(customerRaw);
  const productName = cleanProduct(productRaw);
  if (!customerName || !productName) continue;

  purchases.push({
    customer_name: customerName,
    product_name: productName,
    order_no: toText(row.order_no, row.order_number, row.invoice_no, row.nota_no, row.id),
  });
}

if (purchases.length === 0) {
  return [{
    json: {
      ...config,
      skipped: true,
      skip_reason: 'Tidak ada pembelian berbayar dengan nama pelanggan dan produk yang bisa dipakai pada ' + config.business_date + '.',
      candidate_count: rows.length,
      top_level_fields: Object.keys(response ?? {}),
    },
  }];
}

const featured = purchases[0];
const thankyouText =
  'Terima kasih kak ' + featured.customer_name +
  ' yang telah membeli ' + featured.product_name +
  ' di Grandivo, semoga bermanfaat.';

return [{
  json: {
    ...config,
    skipped: false,
    customer_name: featured.customer_name,
    product_name: featured.product_name,
    order_no: featured.order_no,
    purchase_count: purchases.length,
    source: 'olsera-salesdetails',
    thankyou_text: thankyouText,
  },
}];

const input = $input.first().json;
const TITLE_SKIP = new Set([
  'bapak', 'ibu', 'pak', 'bu', 'kak', 'mas', 'mba', 'mbak',
  'sdr', 'sdri', 'tn', 'ny', 'bpk', 'bpk.', 'ibu.',
]);

const toFirstName = (fullName) => {
  const cleaned = String(fullName || '')
    .replace(/[^A-Za-zÀ-ÿ' .\-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!cleaned) return '';
  const parts = cleaned.split(' ').filter(Boolean);
  const picked = TITLE_SKIP.has(parts[0].toLowerCase()) ? (parts[1] || '') : parts[0];
  if (!picked || picked.length < 2) return '';
  return picked.charAt(0).toUpperCase() + picked.slice(1).toLowerCase();
};

const customerName = toFirstName(input.customer_name);
const productName = String(input.product_name || '').replace(/\s+/g, ' ').trim();
if (!customerName || !productName) {
  throw new Error('Nama pelanggan atau produk kosong sebelum meminta naskah Grok.');
}

const thankyouText =
  input.thankyou_text ||
  ('Terima kasih kak ' + customerName + ' yang telah membeli ' + productName + ' di Grandivo, semoga bermanfaat.');

return [{
  json: {
    ...input,
    customer_name: customerName,
    product_name: productName,
    thankyou_text: thankyouText,
    source: input.source || 'manual',
  },
}];

