const response = $input.first().json;
const prepared = $('Normalisasi Nama & Naskah').first().json;
const content = String(
  response?.choices?.[0]?.message?.content ??
  response?.output_text ??
  ''
).trim();

let parsed = {};
if (content) {
  const match = content.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (error) {
      parsed = {};
    }
  }
}

const thankyouText = prepared.thankyou_text;
const onScreenText = String(parsed.on_screen_text || thankyouText).trim();
const spokenScript = String(parsed.spoken_script || thankyouText).trim();
let videoPrompt = String(parsed.video_prompt || '').trim();

if (!videoPrompt) {
  videoPrompt =
    'Vertical 9:16 cinematic commercial for Grandivo, a modern Indonesian electronics store. ' +
    'Warm lighting, clean gadget boutique, friendly host facing camera. ' +
    'Large readable Indonesian on-screen text exactly: \"' + thankyouText + '\". ' +
    'The host speaks the same sentence in warm natural Indonesian. ' +
    'No extra captions, no other brand logos, no invented customer details.';
}

if (!onScreenText.includes(prepared.customer_name) || !onScreenText.toLowerCase().includes('grandivo')) {
  throw new Error('Naskah Grok tidak mengandung nama pelanggan atau Grandivo.');
}

return [{
  json: {
    ...prepared,
    on_screen_text: onScreenText,
    spoken_script: spokenScript,
    video_prompt: videoPrompt,
    grok_chat_model: response?.model || prepared.chat_model,
  },
}];

const generated = $input.first().json;
const prepared = $('Validasi Naskah Grok').first().json;
const requestId = String(
  generated.request_id ||
  generated.id ||
  generated?.data?.request_id ||
  generated?.data?.id ||
  ''
).trim();

if (!requestId) {
  throw new Error(
    'request_id video Grok tidak ditemukan. Field tingkat atas: ' +
    (Object.keys(generated ?? {}).join(', ') || '(kosong)') + '.'
  );
}

return [{
  json: {
    ...prepared,
    request_id: requestId,
    poll_count: 0,
    continue_poll: true,
    video_status: 'pending',
  },
}];

const statusPayload = $input.first().json;
const waiting = $('Tunggu Proses Video').first().json;
const status = String(
  statusPayload.status ||
  statusPayload?.data?.status ||
  ''
).toLowerCase();
const pollCount = Number(waiting.poll_count || 0) + 1;
const maxPolls = Number(waiting.max_polls || 30);

if (status === 'done') {
  const videoUrl = String(
    statusPayload?.video?.url ||
    statusPayload?.data?.video?.url ||
    statusPayload?.url ||
    statusPayload?.data?.url ||
    ''
  ).trim();
  if (!videoUrl) {
    throw new Error('Video Grok berstatus done tetapi URL kosong.');
  }
  return [{
    json: {
      ...waiting,
      poll_count: pollCount,
      continue_poll: false,
      skipped: false,
      video_status: 'done',
      video_url: videoUrl,
      video_duration_result: statusPayload?.video?.duration ?? statusPayload?.data?.video?.duration ?? waiting.video_duration,
    },
  }];
}

if (status === 'failed' || status === 'expired') {
  const message = statusPayload?.error?.message || statusPayload?.data?.error?.message || status;
  throw new Error('Generate video Grok gagal (' + status + '): ' + message);
}

if (pollCount >= maxPolls) {
  throw new Error(
    'Video Grok belum selesai setelah ' + pollCount +
    ' kali cek. request_id=' + waiting.request_id
  );
}

return [{
  json: {
    ...waiting,
    poll_count: pollCount,
    continue_poll: true,
    video_status: status || 'pending',
  },
}];

const input = $input.first().json;
const timestamp = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });

if (input.skipped) {
  return [{
    json: {
      status: 'SKIPPED',
      message: input.skip_reason || 'Tidak ada video yang dibuat.',
      business_date: input.business_date,
      candidate_count: input.candidate_count || 0,
      synced_at_wib: timestamp,
    },
  }];
}

if (!input.video_url) {
  throw new Error('Workflow selesai tanpa video_url.');
}

return [{
  json: {
    status: 'SUCCESS',
    message: 'Video terima kasih harian siap.',
    business_date: input.business_date,
    customer_name: input.customer_name,
    product_name: input.product_name,
    thankyou_text: input.thankyou_text,
    video_url: input.video_url,
    request_id: input.request_id,
    video_model: input.video_model,
    poll_count: input.poll_count,
    source: input.source,
    synced_at_wib: timestamp,
    note: 'URL video xAI bersifat sementara. Unduh segera jika perlu disimpan.',
  },
}];
